$testOneDriveRoot=if($env:SMART_EXPENSE_TEST_ONEDRIVE_ROOT){Get-HermesOneDriveRoot -ExplicitRoot $env:SMART_EXPENSE_TEST_ONEDRIVE_ROOT}else{Get-HermesOneDriveRoot}
$script:SourceWorkbook=Join-Path $testOneDriveRoot 'Documents\2_Others\Expenses_finance\Canada plan.xlsx'
