$passed = 0
function Assert-Equal([object]$Actual,[object]$Expected,[string]$Message) { if ($Actual -cne $Expected) { throw "$Message Expected=[$Expected] Actual=[$Actual]" }; $script:passed++ }
function Assert-True([bool]$Condition,[string]$Message) { if (-not $Condition) { throw $Message }; $script:passed++ }
function Assert-Throws([scriptblock]$Action,[string]$Message) { $thrown=$false;try{&$Action}catch{$thrown=$true};if(-not $thrown){throw $Message};$script:passed++ }
function New-TestRoot { $path=Join-Path ([IO.Path]::GetTempPath()) ('smart-expense-test-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force -Path $path|Out-Null;return $path }
function Write-TestJson([string]$Path,[object]$Payload) { $Payload|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $Path -Encoding utf8 }
function New-TestPayload([string]$Id,[string]$CreatedAt,[string]$ReceiptDate,[string]$Merchant,[decimal]$Amount,[string]$Currency='CAD') {
    $guid=[guid]$Id;$stamp=[datetimeoffset]$CreatedAt;$short=$guid.ToString('N').Substring(0,8).ToLowerInvariant()
    return [pscustomobject]@{schemaVersion=2;expenseId=$guid.ToString();createdAt=$CreatedAt;sourceDeviceId='test-phone';receiptDate=$ReceiptDate;merchantName=$Merchant;totalAmount=$Amount;currency=$Currency;extractionStatus='confirmed';receiptImageRelativePath=("Documents/2_Others/Expenses_finance/receipt_images/{0}/{1}_receipt_{2}.jpg" -f $stamp.ToString('yyyy-MM'),$stamp.ToString('yyyyMMdd_HHmmss'),$short)}
}
function Add-TestHandoff([string]$Root,[object]$Payload,[string]$TimestampForFile) {
    $expense=Join-Path $Root 'Documents\2_Others\Expenses_finance';$inbox=Join-Path $expense 'logs';$month=$Payload.receiptImageRelativePath.Split('/')[5];$image=Join-Path $Root ($Payload.receiptImageRelativePath -replace '/', '\');New-Item -ItemType Directory -Force -Path $inbox,(Split-Path -Parent $image)|Out-Null;New-Item -ItemType File -Force -Path $image|Out-Null;$short=([guid]$Payload.expenseId).ToString('N').Substring(0,8).ToLowerInvariant();$file="expense_${TimestampForFile}_$short.json";$path=Join-Path $inbox $file;Write-TestJson $path $Payload;return $path
}
function Copy-DisposableWorkbook([string]$Root) {
    $expense=Join-Path $Root 'Documents\2_Others\Expenses_finance';New-Item -ItemType Directory -Force -Path (Join-Path $expense 'logs')|Out-Null;Copy-Item -LiteralPath $script:SourceWorkbook -Destination (Join-Path $expense 'Canada plan.xlsx');return (Join-Path $expense 'Canada plan.xlsx')
}
function Set-WorkbookSentinel([string]$WorkbookPath) {
    $excel=$null;$book=$null;try{
        $excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$book=$excel.Workbooks.Open($WorkbookPath,$null,$false);$sheet=$book.Worksheets.Item('2026-09')
        $partialRow=$null;$targetRow=$null
        for($row=12;$row -le 99;$row++){
            $currentFree=[string]::IsNullOrWhiteSpace([string]$sheet.Cells.Item($row,6).Value2) -and [string]::IsNullOrWhiteSpace([string]$sheet.Cells.Item($row,7).Value2)
            $nextFree=[string]::IsNullOrWhiteSpace([string]$sheet.Cells.Item($row+1,6).Value2) -and [string]::IsNullOrWhiteSpace([string]$sheet.Cells.Item($row+1,7).Value2)
            if($currentFree -and $nextFree){$partialRow=$row;$targetRow=$row+1;break}
        }
        if($null -eq $partialRow){throw 'No adjacent safe transaction rows available for the structural-warning canary.'}
        $sheet.Cells.Item($partialRow,6).Value2=[double]9;$sheet.Cells.Item($targetRow,5).Value2=[double]0.5;$sheet.Cells.Item($targetRow,16).Value2='sentinel-unrelated';$book.Save();return $targetRow
    }finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}
}function Remove-DisposableSheet([string]$WorkbookPath,[string]$Name) {
    $excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$excel.DisplayAlerts=$false;$book=$excel.Workbooks.Open($WorkbookPath,$null,$false);$book.Worksheets.Item($Name).Delete();$book.Save()}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}}
function Get-SummaryUsedRowCount([string]$WorkbookPath) {
    $excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$book=$excel.Workbooks.Open($WorkbookPath,$null,$true);return [int]$book.Worksheets.Item('Food Expense Summary').UsedRange.Rows.Count}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}}
