Assert-Equal (Normalize-HermesMerchant ' CAFÉ,   Supermarket! ') 'café mart' 'Merchant comparison normalization failed.';Assert-Equal (Format-HermesMerchantDescription ' Example   Supermarket ' '2026-09-05') 'Example Mart Sep 05' 'Merchant display formatting failed.'
Assert-Equal (Get-HermesLegacyReceiptDate '2026-09' 'Example Mart Sep 05').ToString('yyyy-MM-dd') '2026-09-05' 'Legacy date parser failed.';Assert-True ($null -eq (Get-HermesLegacyReceiptDate '2026-09' 'Example Sep 05 and Oct 01')) 'Ambiguous legacy date was guessed.';Assert-True ($null -eq (Get-HermesLegacyReceiptDate '2026-09' 'Example Aug 05')) 'Wrong-month legacy date was accepted.'
$safe=Find-HermesSafeTransactionRow @(@{F=1;G=$null},@{F=$null;G='occupied'},@{F=$null;G=$null}) 12;Assert-Equal $safe.Row 14 'Safe row selection failed.';Assert-Equal $safe.Warnings.Count 2 'Partial row warnings failed.';Assert-True (-not (Find-HermesSafeTransactionRow (@(1..89|ForEach-Object {@{F=$_;G="x$_"}})) 12).HasCapacity) 'Full transaction capacity was not detected.'

