$payload.receiptImageRelativePath='../escape.jpg';Assert-True (-not (Test-HermesVersion2Handoff $payload (Split-Path -Leaf $validPath) $root).Valid) 'Traversal image path was accepted.';$payload=New-TestPayload 'bbbbbbbb-2222-4222-8222-222222222222' '2026-09-05T12:34:56-07:00' '2026-09-05' 'Example Shop' 42.35;$payload.extractionStatus='low_confidence';$badStatusPath=Add-TestHandoff $root $payload '20260905_123457';Assert-Equal (Test-HermesVersion2Handoff $payload (Split-Path -Leaf $badStatusPath) $root).ReasonCode 'invalid_status' 'Disallowed status was accepted.';$payload=New-TestPayload 'cccccccc-3333-4333-8333-333333333333' '2026-09-05T12:34:56-07:00' '2026-09-05' 'Example Shop' 42.35;$payload.currency='USD';$nonCadPath=Add-TestHandoff $root $payload '20260905_123458';$v=Test-HermesVersion2Handoff $payload (Split-Path -Leaf $nonCadPath) $root;Assert-True $v.Valid 'Valid non-CAD handoff was rejected before review.'
$record=[pscustomobject]@{ReceiptDate=[datetime]'2026-09-05';Amount=42.35;NormalizedMerchant=(Normalize-HermesMerchant 'Example Supermarket');Sheet='2026-09';Row=30};$exact=Get-HermesDuplicateDecision ([pscustomobject]@{ReceiptDate=[datetime]'2026-09-05';Amount=42.350;NormalizedMerchant='example mart'}) @($record);Assert-Equal $exact.Outcome 'exact_duplicate' 'Exact duplicate classification failed.';$similar=Get-HermesDuplicateDecision ([pscustomobject]@{ReceiptDate=[datetime]'2026-09-05';Amount=42.35;NormalizedMerchant='other merchant'}) @($record);Assert-Equal $similar.Outcome 'review' 'Same-date/amount review classification failed.';$distinct=Get-HermesDuplicateDecision ([pscustomobject]@{ReceiptDate=[datetime]'2026-09-06';Amount=42.35;NormalizedMerchant='other merchant'}) @($record);Assert-Equal $distinct.Outcome 'inserted' 'Distinct record classification failed.'

