# A real overlapping process lock is reported and logged instead of being silent.
$lockRoot=New-TestRoot;$lockInbox=Join-Path $lockRoot 'Documents\2_Others\Expenses_finance\logs';New-Item -ItemType Directory -Force -Path $lockInbox|Out-Null;$lockReady=Join-Path $lockRoot 'ready';$lockJob=Start-Job -ArgumentList $lockReady -ScriptBlock {param($ready)$mutex=[Threading.Mutex]::new($false,'Global\SmartExpenseTracking.HermesExcelUpdate');try{if(-not $mutex.WaitOne(0)){throw 'lock unavailable'};Set-Content -LiteralPath $ready -Value ready;Start-Sleep -Seconds 30}finally{try{$mutex.ReleaseMutex()}catch{};$mutex.Dispose()}};try{for($i=0;$i -lt 100 -and -not (Test-Path $lockReady);$i++){Start-Sleep -Milliseconds 50};Assert-True (Test-Path $lockReady) 'Lock-holder process did not become ready.';$lockLog=Join-Path $lockRoot 'processor.jsonl';$lockResult=Invoke-HermesProcessor -OneDriveRoot $lockRoot -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $lockRoot 'state.json') -LogPath $lockLog;Assert-Equal $lockResult.items[0].reasonCode 'processor_locked' 'Overlapping run was not classified as processor_locked.';Assert-True ((Format-HermesOutput $lockResult 'Hermes') -ne '[SILENT]') 'Overlapping run was incorrectly suppressed.';Assert-True (Test-Path $lockLog) 'Overlapping-run result was not logged.'}finally{Stop-Job $lockJob -ErrorAction SilentlyContinue;Remove-Job $lockJob -Force -ErrorAction SilentlyContinue}

