$source=$script:SourceWorkbook
$canary=New-TestRoot;$canaryWorkbook=Copy-DisposableWorkbook $canary;$null=Set-WorkbookSentinel $canaryWorkbook;$canaryPayload=New-TestPayload 'eeeeeeee-5555-4555-8555-555555555555' '2026-09-05T12:34:56-07:00' '2026-09-05' '=Example Supermarket' 42.35;$canaryPath=Add-TestHandoff $canary $canaryPayload '20260905_123458';$canaryState=Join-Path $canary 'state.json';$canaryLog=Join-Path $canary 'processor.jsonl';$beforeHash=Get-HermesFileSha256 $canaryWorkbook;$dry=Invoke-HermesProcessor -OneDriveRoot $canary -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath $canaryState -LogPath $canaryLog -DryRun;Assert-Equal $dry.counts.discovered 1 'DryRun discovery count failed.';Assert-Equal $dry.counts.failed 0 'DryRun incorrectly counted an eligible item as failed.';Assert-Equal $dry.items[0].outcome 'eligible' 'DryRun did not report an eligible item.';Assert-True (-not (Test-Path $canaryState)) 'DryRun wrote state.';Assert-Equal (Get-HermesFileSha256 $canaryWorkbook) $beforeHash 'DryRun changed the workbook.'
$write=Invoke-HermesProcessor -OneDriveRoot $canary -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath $canaryState -LogPath $canaryLog;Assert-Equal $write.counts.inserted 1 'COM canary did not insert.';Assert-Equal $write.items[0].reasonCode 'inserted_with_structural_warning' 'Partial transaction rows were not reported with the successful insert.';Assert-True (Test-Path (Join-Path $canary 'Documents/2_Others/Expenses_finance/logs/receipt_jsons_done/expense_20260905_123458_eeeeeeee.json')) 'Canary handoff was not archived.'
$excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$book=$excel.Workbooks.Open($canaryWorkbook,$null,$true);$sheet=$book.Worksheets.Item('2026-09');$summary=$book.Worksheets.Item('Food Expense Summary');$found=@();for($r=12;$r -le 100;$r++){if([string]$sheet.Cells.Item($r,7).Value2 -eq '=Example Mart Sep 05'){$found+=$r}};Assert-Equal $found.Count 1 'Canary inserted row count is not one.';$r=$found[0];Assert-Equal ([decimal]$sheet.Cells.Item($r,6).Value2) ([decimal]42.35) 'Canary F amount is not numeric/correct.';Assert-True (-not [bool]$sheet.Cells.Item($r,7).HasFormula) 'Merchant text beginning with = was interpreted as an Excel formula.';Assert-Equal $sheet.Cells.Item($r,8).Hyperlinks.Item(1).Address 'receipt_images\2026-09\20260905_123456_receipt_eeeeeeee.jpg' 'Canary H hyperlink is not relative.';Assert-Equal ([double]$sheet.Cells.Item($r,5).Value2) ([double]0.5) 'Canary E was not preserved.';Assert-Equal $sheet.Cells.Item($r,16).Value2 'sentinel-unrelated' 'Canary unrelated cell was not preserved.';Assert-True ([string]$sheet.Cells.Item($r,15).Formula -match 'E30|E\d+') 'Canary O formula was not preserved/extended.';Assert-Equal $sheet.Cells.Item($r,6).Style.NameLocal $sheet.Cells.Item(29,6).Style.NameLocal 'Canary row style was not preserved/extended.';Assert-Equal $book.Worksheets.Count 47 'Canary workbook sheet/object count changed.';Assert-Equal $summary.Cells.Item(17,6).Value2 'OK' 'Canary summary coverage failed.';Assert-True ([string]$summary.Cells.Item(1,1).Value2 -match '2026-09') 'Canary summary title was not extended.'}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}

