$replay=Join-Path $canary 'Documents/2_Others/Expenses_finance/logs/expense_20260905_123458_eeeeeeee.json';Copy-Item (Join-Path $canary 'Documents/2_Others/Expenses_finance/logs/receipt_jsons_done/expense_20260905_123458_eeeeeeee.json') $replay;$replayState=Join-Path $canary 'replay-state.json';$replayRun=Invoke-HermesProcessor -OneDriveRoot $canary -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath $replayState -LogPath (Join-Path $canary 'replay.jsonl');Assert-Equal $replayRun.counts.exactDuplicate 1 'Workbook-level exact duplicate was not detected.'

# Multiple files stay in ordinal result order and detect staged exact/similar duplicates within one COM batch.
$batch=New-TestRoot;$batchWorkbook=Copy-DisposableWorkbook $batch;$batchA=New-TestPayload '14141414-1111-4111-8111-111111111111' '2026-09-11T10:00:00-07:00' '2026-09-11' 'Batch Alpha' 8765.43;$batchB=New-TestPayload '15151515-2222-4222-8222-222222222222' '2026-09-11T10:01:00-07:00' '2026-09-11' 'Batch Alpha' 8765.43;$batchC=New-TestPayload '16161616-3333-4333-8333-333333333333' '2026-09-11T10:02:00-07:00' '2026-09-11' 'Batch Beta' 8765.43;$batchPathA=Add-TestHandoff $batch $batchA '20260911_100000';$batchPathB=Add-TestHandoff $batch $batchB '20260911_100100';$batchPathC=Add-TestHandoff $batch $batchC '20260911_100200';$batchRun=Invoke-HermesProcessor -OneDriveRoot $batch -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $batch 'state.json') -LogPath (Join-Path $batch 'processor.jsonl');Assert-Equal $batchRun.counts.inserted 1 'Batch insert count failed.';Assert-Equal $batchRun.counts.exactDuplicate 1 'Staged exact duplicate was not detected.';Assert-Equal $batchRun.counts.review 1 'Staged similar record was not quarantined.';Assert-Equal (($batchRun.items|ForEach-Object fileName) -join ',') ((Split-Path -Leaf $batchPathA)+','+(Split-Path -Leaf $batchPathB)+','+(Split-Path -Leaf $batchPathC)) 'Batch result order was not ordinal.';$batchExact=$batchRun.items|Where-Object outcome -eq 'exact_duplicate'|Select-Object -First 1;Assert-True ($null -ne $batchExact.row -and $batchExact.sheet -eq '2026-09') 'Staged exact duplicate did not report the staged candidate row.';Assert-True (Test-Path (Join-Path $batch 'Documents/2_Others/Expenses_finance/logs/receipt_jsons_review/expense_20260911_100200_16161616.result.json')) 'Staged similar-record review sidecar was not written.'

# Missing-month copy and summary extension on a second disposable copy.
$future=New-TestRoot;$futureWorkbook=Copy-DisposableWorkbook $future;$futureRowsBefore=Get-SummaryUsedRowCount $futureWorkbook;$futurePayload=New-TestPayload 'ffffffff-6666-4666-8666-666666666666' '2026-10-06T12:34:56-07:00' '2026-10-06' 'Future Supermarket' 8.75;$futurePath=Add-TestHandoff $future $futurePayload '20261006_123456';$futureRun=Invoke-HermesProcessor -OneDriveRoot $future -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $future 'state.json') -LogPath (Join-Path $future 'log.jsonl');Assert-Equal $futureRun.counts.inserted 1 'Missing-month canary did not insert.';$excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$book=$excel.Workbooks.Open($futureWorkbook,$null,$true);Assert-True ($null -ne $book.Worksheets.Item('2026-09')) 'Missing month was not copied.';Assert-Equal $book.Worksheets.Item('Food Expense Summary').Cells.Item(17,6).Value2 'OK' 'Missing-month summary coverage failed.';Assert-Equal ([int]$book.Worksheets.Item('Food Expense Summary').UsedRange.Rows.Count) ($futureRowsBefore+90) 'Summary extension copied more than one 89-row detail block.';$futureSummaryModel=Get-HermesSummaryModel $book;Assert-True ([string]::IsNullOrWhiteSpace([string]$book.Worksheets.Item('Food Expense Summary').Cells.Item($futureSummaryModel.DetailEnd+1,1).Value2)) 'Summary extension left copied detail rows beyond the new 89-row block.'}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}

# Missing intermediate months are placed before the earliest later monthly sheet.
$ordering=New-TestRoot;$orderingWorkbook=Copy-DisposableWorkbook $ordering;$excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$excel.DisplayAlerts=$false;$book=$excel.Workbooks.Open($orderingWorkbook,$null,$false);$book.Worksheets.Item('2026-08').Delete();$created=Ensure-HermesMonthlySheet $book '2026-08';Assert-True ($book.Worksheets.Item('2026-07').Index -lt $created.Index -and $created.Index -lt $book.Worksheets.Item('2026-09').Index) 'Missing monthly sheet was not placed chronologically before the earliest later month.'}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()}

# Full transaction capacity defers without saving or moving the valid handoff.
$full=New-TestRoot;$fullWorkbook=Copy-DisposableWorkbook $full;$excel=$null;$book=$null;try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$book=$excel.Workbooks.Open($fullWorkbook,$null,$false);$sheet=$book.Worksheets.Item('2026-09');for($r=12;$r -le 100;$r++){$sheet.Cells.Item($r,6).Value2=[double]$r;$sheet.Cells.Item($r,7).Value2="Occupied $r"};$book.Save()}finally{if($book){$book.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($book)|Out-Null};if($excel){$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null};[GC]::Collect();[GC]::WaitForPendingFinalizers()};$fullPayload=New-TestPayload '18181818-5555-4555-8555-555555555555' '2026-09-13T12:00:00-07:00' '2026-09-13' 'Capacity Shop' 12.5;$fullPath=Add-TestHandoff $full $fullPayload '20260913_120000';$fullHash=Get-HermesFileSha256 $fullWorkbook;$fullRun=Invoke-HermesProcessor -OneDriveRoot $full -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $full 'state.json') -LogPath (Join-Path $full 'processor.jsonl');Assert-Equal $fullRun.counts.deferred 1 'Full transaction range did not defer the handoff.';Assert-True (Test-Path $fullPath) 'Full transaction range removed the handoff.';Assert-Equal (Get-HermesFileSha256 $fullWorkbook) $fullHash 'Full transaction range changed the workbook.'

# Existing Excel owner files defer valid handoffs without opening the workbook.
$locked=New-TestRoot;$lockedWorkbook=Copy-DisposableWorkbook $locked;$lockedPayload=New-TestPayload '17171717-4444-4444-8444-444444444444' '2026-09-12T12:00:00-07:00' '2026-09-12' 'Locked Shop' 11.25;$lockedPath=Add-TestHandoff $locked $lockedPayload '20260912_120000';New-Item -ItemType File -Force -Path (Join-Path (Split-Path -Parent $lockedWorkbook) '~$Canada plan.xlsx')|Out-Null;$lockedRun=Invoke-HermesProcessor -OneDriveRoot $locked -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $locked 'state.json') -LogPath (Join-Path $locked 'processor.jsonl');Assert-Equal $lockedRun.counts.deferred 1 'Excel owner lock did not defer the handoff.';Assert-True (Test-Path $lockedPath) 'Excel owner lock removed the handoff from the inbox.'

# Injected pre-save failure leaves the disposable workbook and handoff untouched.
$preSave=New-TestRoot;$preSaveWorkbook=Copy-DisposableWorkbook $preSave;$preSavePayload=New-TestPayload '19191919-6666-4666-8666-666666666666' '2026-09-14T12:00:00-07:00' '2026-09-14' 'Pre Save Shop' 13.5;$preSavePath=Add-TestHandoff $preSave $preSavePayload '20260914_120000';$preSaveHash=Get-HermesFileSha256 $preSaveWorkbook;$preSaveRun=Invoke-HermesProcessor -OneDriveRoot $preSave -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $preSave 'state.json') -LogPath (Join-Path $preSave 'processor.jsonl') -WorkbookUpdater {param($w,$i,$d) throw 'injected_pre_save_failure'};Assert-Equal $preSaveRun.counts.failed 1 'Pre-save failure was not surfaced.';Assert-True (Test-Path $preSavePath) 'Pre-save failure removed the handoff.';Assert-Equal (Get-HermesFileSha256 $preSaveWorkbook) $preSaveHash 'Pre-save failure changed the workbook.'

# Read-only workbook and post-save archive-failure recovery remain conservative and retryable.
$readOnly=New-TestRoot;$readOnlyWorkbook=Copy-DisposableWorkbook $readOnly;$readOnlyPayload=New-TestPayload '12121212-7777-4777-8777-777777777777' '2026-09-07T12:34:56-07:00' '2026-09-07' 'Read Only Shop' 3.25;$readOnlyPath=Add-TestHandoff $readOnly $readOnlyPayload '20260907_123456';(Get-Item -LiteralPath $readOnlyWorkbook).IsReadOnly=$true;try{$readOnlyRun=Invoke-HermesProcessor -OneDriveRoot $readOnly -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $readOnly 'state.json') -LogPath (Join-Path $readOnly 'log.jsonl');Assert-Equal $readOnlyRun.counts.deferred 1 'Read-only workbook was not deferred.';Assert-True (Test-Path $readOnlyPath) 'Read-only workbook lost the handoff.'}finally{(Get-Item -LiteralPath $readOnlyWorkbook).IsReadOnly=$false}
$archiveFailure=New-TestRoot;$archivePayload=New-TestPayload '13131313-8888-4888-8888-888888888888' '2026-09-08T12:34:56-07:00' '2026-09-08' 'Archive Failure Shop' 4.5;$archivePath=Add-TestHandoff $archiveFailure $archivePayload '20260908_123456';$archiveUpdate={param($w,$i,$d) [pscustomobject]@{Saved=$true;Items=@([pscustomobject]@{FileName=(Split-Path -Leaf $archivePath);ExpenseId=$archivePayload.expenseId;Outcome='inserted';ReasonCode='inserted';Message='fake';Sheet='2026-09';Row=12;Candidates=@()})}};$archiveMover={param($s,$d,$complete) throw 'injected_archive_failure'};$archiveRun=Invoke-HermesProcessor -OneDriveRoot $archiveFailure -InboxRelativePath 'Documents/2_Others/Expenses_finance/logs' -WorkbookRelativePath 'Documents/2_Others/Expenses_finance/Canada plan.xlsx' -StatePath (Join-Path $archiveFailure 'state.json') -LogPath (Join-Path $archiveFailure 'log.jsonl') -WorkbookUpdater $archiveUpdate -ArchiveMover $archiveMover;Assert-Equal $archiveRun.counts.failed 1 'Archive failure was not surfaced.';Assert-True (Test-Path $archivePath) 'Archive failure incorrectly removed the handoff.';Assert-True (Test-Path (Join-Path $archiveFailure 'state.json')) 'Post-save state was not persisted before archive failure.'

